.slogan
{
	font-family:Arial, Helvetica, sans-serif;
	font-size:13px;
	font-weight:bold;
	color:993311;
	font-style:italic;
}
.nav1
{
	font-family:Verdana, Arial, Helvetica, sans-serif;
	font-size:12px;
	font-weight:bold;
	text-decoration:none;
	padding:3px;
	color:#ffffff;
	background-color:#ff0000;
	line-height:10px;
	background-position:center center;
	text-transform:none;
	word-spacing:normal;
	letter-spacing:normal;
	vertical-align:auto;
	white-space:normal;
	margin:0px;
	border:1px none #ffffff;
	text-align:center;
}
.nav1active
{
	font-family:Tahoma, Geneva, sans-serif;
	font-size:13px;
	font-weight:bold;
	color:#ffffff;
	text-decoration:none;
	padding:0px;
	background-color:#ffffff;
	vertical-align:auto;
	line-height:10px;
}
.nav1:hover
{
	color:#ffffff;
	background-color:#ff0000;
	border:'' '' #ffffff;
}
.nav1background
{
	background-color:#ff0000;
	color:#ffffff;
